 # The same full-cell embeddings use four equal windows and a dedicated shared legend band.
 atlas_one<-function(dataset,id){
  d<-read.csv(file.path(DATA,paste0('atlas_',dataset,'.csv.gz')));d$cell_type<-shortct(d$celltype)
  q<-P(id,'3_B',d,color='cell_type',legend=FALSE)+scale_color_manual(values=cell_palette,name=NULL)+theme_void()+theme(text=element_text(family='Helvetica',size=12),legend.position='none',strip.text=element_text(size=13,face='bold'),plot.margin=margin(25,8,8,8))+facet_wrap(~dataset,ncol=1,labeller=labeller(dataset=c(human_blood='Human blood',human_brain='Human brain',mouse_blood='Mouse blood',mouse_brain='Mouse brain')))
  q$layers[[1]]$aes_params$size<-.5;q$layers[[1]]$aes_params$alpha<-.8
  xr<-range(d$x);yr<-range(d$y);radius<-.54*max(diff(xr),diff(yr));q<-q+coord_equal(xlim=mean(xr)+c(-radius,radius),ylim=mean(yr)+c(-radius,radius),expand=FALSE);q
 }
