d<-rd('priority_drugs');d$cell_type<-d$clinical_max_phase;d$regulon<-factor(paste(d$protein,d$drug,sep=' | '),rev(unique(paste(d$protein,d$drug,sep=' | '))));d$auc<-1;d$expression<-d$clinical_max_phase;p<-P('7b','5_E',d)+aes(shape=action)+scale_shape_manual(values=c(AGONIST=24,ANTAGONIST=25,INHIBITOR=21,`BINDING AGENT`=22,OTHER=23,`PARTIAL AGONIST`=8),name='Mechanism')+scale_fill_gradient(low='#D4E8DB',high='#398B82',name='Clinical max phase')+scale_size(range=c(3.5,3.5),guide='none')+scale_x_continuous(breaks=1:4,limits=c(.5,4.45),expand=c(0,0))+labs(x='Highest clinical phase',y=NULL)+theme(axis.text.x=element_text(angle=0),axis.text.y=element_text(size=12),legend.position='bottom')+box;p$layers[[1]]$aes_params$shape<-NULL;p<-p+theme(legend.box='horizontal',legend.box.just='center',legend.spacing.x=unit(5,'mm'))+guides(shape=guide_legend(ncol=2,title.position='top',override.aes=list(size=3,fill='#83A7A0')),fill=guide_colorbar(title.position='top',barwidth=unit(28,'mm')))+labs(shape='Action',fill='Clinical phase');track<-geom_segment(data=d,aes(x=.65,xend=clinical_max_phase,y=regulon,yend=regulon),inherit.aes=FALSE,color='#B9CCC8',linewidth=.65);p$layers<-c(list(track),p$layers);p<-p+theme(panel.grid.major.x=element_line(color='#E4EBE8',linewidth=.25))+scale_y_discrete(labels=function(x)wrap(sub('^[^|]+ [|] ','',x),24))+facet_grid(protein~.,scales='free_y',space='free_y')+theme(strip.text.y=element_text(angle=0,size=13,face='bold'));export(p,'7b',3,4)
d<-rd('priority_matrix');d$cell_type<-factor(paste(short(d$blood_state),short(d$brain_state),sep=' > '));d$region<-factor(paste(d$protein,d$program_definition,d$response_direction,sep=' | '));d$delta<-d$n_genes;d$treatment<-'Current programs';p<-P('7c','6_J',d)+facet_null()+scale_fill_gradient(low='#E6F0EA',high='#398B82',name='Program genes',breaks=c(40,60,80))+guides(fill=guide_colorbar(title.position='top',barwidth=unit(34,'mm')))+geom_text(aes(label=n_genes),size=12/ggplot2::.pt)+theme(axis.text.x=element_text(angle=50,hjust=1,size=12),axis.text.y=element_text(size=12),legend.position='bottom');export(p,'7c',3,2)
